SELECT count(1) count, min(oupprd.id) min_id, max(oupprd.id) max_id
FROM dwd_user_event oupprd
WHERE oupprd.dates = #{dates}

    and oupprd.event_id in

        #{event}

SELECT oupprd.id, oupprd.dates, oupprd.user_id, oupprd.event_id, oupprd.event_msg, oupprd.version, oupprd.pkg, dui.dates register_date, oupprd.create_time FROM dwd_user_event oupprd INNER JOIN dim_user_info dui on (oupprd.user_id = dui.user_id) WHERE oupprd.dates = #{dates}
and oupprd.event_id in
#{event}
and oupprd.id >= #{startId} and oupprd.id <= #{endId}

SELECT oupprd.id, oupprd.dates, oupprd.user_id, oupprd.event_id, oupprd.event_msg, oupprd.version, oupprd.pkg, dui.dates register_date, IFNULL(dus.network, 'Unknown') user_source, oupprd.create_time FROM dwd_user_event oupprd INNER JOIN dim_user_info dui on (oupprd.user_id = dui.user_id) left join dim_user_source dus on (dui.user_id = dus.user_id) WHERE oupprd.dates = #{dates}
and oupprd.event_id in
#{event}
and oupprd.id >= #{startId} and oupprd.id <= #{endId}
